async def act(page):
    """
    Steps:
    1. Open the Prices tab for the current product.
    2. Locate the Price input, read its current value.
    3. Compute a 15% reduction, format to two decimals.
    4. Fill the new price value and save the product.

    Note: There are no functions in the provided knowledge base to call for this task.
    """
    import re

    # 1) Click the Prices tab link (use the long accessibility name that is present in the tree)
    prices_link = page.get_by_role(
        "link",
        name=(
            "The information in this tab has been changed. This tab contains invalid data. "
            "Please solve the problem before saving. Prices"
        ),
    )
    await prices_link.click()

    # Give the UI a brief moment to render the Prices section
    await page.wait_for_timeout(800)

    # 2) Locate the price input. Try accessible role lookup first, then fallback to label lookup.
    price_input = None
    try:
        price_input = page.get_by_role("textbox", name="Price")
        # ensure it is visible / attached
        await price_input.wait_for(state="visible", timeout=2000)
    except Exception:
        try:
            price_input = page.get_by_label("Price")
            await price_input.wait_for(state="visible", timeout=2000)
        except Exception:
            # As a last resort, try to find any textbox that contains the word Price in its accessible name
            all_textboxes = page.get_by_role("textbox")
            count = await all_textboxes.count()
            for i in range(count):
                tb = all_textboxes.nth(i)
                try:
                    name = await tb.get_attribute("aria-label")
                except Exception:
                    name = None
                if name and "price" in name.lower():
                    price_input = tb
                    break

    if price_input is None:
        raise Exception("Unable to locate the Price input on the Prices tab")

    # Read current value
    current_value = await price_input.input_value()

    # Extract numeric portion (allow commas and dots), then normalize
    m = re.search(r"[\d,]+(?:\.\d+)?", current_value.replace('\u00a0', ' '))
    if not m:
        # if no numeric part found, try to strip currency symbols and whitespace
        cleaned = re.sub(r"[^0-9.,]", "", current_value)
    else:
        cleaned = m.group(0)

    # Normalize thousand separator commas and convert to float
    cleaned = cleaned.replace(',', '')
    try:
        old_price = float(cleaned)
    except Exception:
        raise Exception(f"Could not parse price value: '{current_value}' (cleaned: '{cleaned}')")

    # 3) Compute new price (reduce by 15%) and format to two decimals
    new_price_value = round(old_price * 0.85, 2)
    new_price_str = f"{new_price_value:.2f}"

    # 4) Fill the new price and save. Use the explicit Save button.
    await price_input.fill(new_price_str)

    # Click Save; this may cause navigation/reload, so make it the last action.
    save_button = page.get_by_role("button", name="Save")
    await save_button.click()

    # Wait briefly for the save to process / page to reload
    try:
        await page.wait_for_load_state("networkidle", timeout=10000)
    except Exception:
        # fallback small pause
        await page.wait_for_timeout(2000)

    # End of actions. The function intentionally does not return anything.

